//! 🧬️ Original transition decoding moves its exact replacement owners into the initialized Store table.
use semio_framework_job::StepContext;
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retirement::controlled::ControlledRetirement};
use std::mem::size_of;
use semio_framework_os_spr as protocol;
use semio_framework_job::{OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeConstructionStepOutcome,NativeConstructionStepFailure,OriginalReceivingPrimary};
pub struct NativeSupersessionSource<'a>{pub event:&'a protocol::MutationEnvelope,pub previous:Option<&'a protocol::MutationEnvelope>,pub document:&'a str,pub line:Option<&'a str>}
type Input=(protocol::CausalPayload,protocol::ArtifactId);
type Output=(protocol::HistoryTransition,String);
#[derive(semio_framework_value::RetireOwned)]
enum Residue{Input(Input),Output(Output),Supersession(protocol::EffectiveSupersession),Failure(TransitionFailure)}
#[derive(Debug,semio_framework_value::RetireOwned)]
struct TransitionFailure{source:protocol::ProtocolError,text:Option<String>}
impl semio_framework_job::OriginalDomainFailure for TransitionFailure{fn domain_code(&self)->&str{"history.transition"}fn domain_message(&self)->&str{self.text.as_deref().unwrap_or("original history transition refused")}fn domain_retained_progress(&self)->RetainedCloneProgress{Default::default()}}
impl semio_framework_job::OriginalDomainProjection for TransitionFailure{fn projection_view(&self,path:&[usize])->Result<semio_framework_job::OriginalDomainView<'_>,ValueError>{match path{[]=>Ok(semio_framework_job::OriginalDomainView::IntrinsicObject(1)),[0]=>Ok(semio_framework_job::OriginalDomainView::IntrinsicText(self.text.as_deref().unwrap_or("original history transition refused"))),_=>Err(invalid("original transition diagnostic projection path changed"))}}fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{if path.is_empty()&&index==0{Ok("message")}else{Err(invalid("original transition diagnostic field changed"))}}}
struct Count(usize);
impl std::fmt::Write for Count{fn write_str(&mut self,text:&str)->std::fmt::Result{self.0=self.0.checked_add(text.len()).ok_or(std::fmt::Error)?;Ok(())}}
pub struct NativeSupersessionFold{input:Option<Input>,job:Option<protocol::HistoryFoldJob<'static,Output>>,output:Option<Output>,retirement:Option<ControlledRetirement<Residue>>,failure:Option<TransitionFailure>,binding:Option<(OriginalSourceBinding,usize)>,offset:usize,done:bool,closing:bool}
impl Default for NativeSupersessionFold{fn default()->Self{Self{input:None,job:None,output:None,retirement:None,failure:None,binding:None,offset:0,done:false,closing:false}}}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn physical(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,text)}
fn receive<T>(cx:&mut StepContext<'_>,run:impl FnOnce(&mut NativeDecodeControl<'_>)->NativeConstructionStepOutcome<T,OriginalReceivingPrimary>)->Result<(),OriginalTurnFailure>{
 let result=cx.with_native_receiving::<_,NativeConstructionStepFailure<OriginalReceivingPrimary>>(|control|{let outcome=run(control);let p=outcome.progress;NativeConstructionStepOutcome{result:outcome.result.map(|result|result.map(|_|RetainedCloneStep::Progress(p))),receipt_refusal:outcome.receipt_refusal,progress:p}.into_step_result()});let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());let context=cx.receiving_issued_grant().map(|grant|cx.consume_receiving_retained(grant,p)).transpose();cx.consume_fuel(p.copied_items as u64);match(result,context){(Ok(_),Ok(_))=>Ok(()),(Err(error),Ok(_))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(context))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=Some(context);Err(failure)}}
}
impl NativeSupersessionFold{
 /// 📏️ Quotes the actual concrete coroutine birth, native work or retained handoff without granting it authority.
 pub fn original_job_demand(&mut self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.retirement.as_ref(){return if owner.terminal_is_empty(){Ok(header::<Option<ControlledRetirement<Residue>>>())}else{owner.next_demand(body)}}if let Some(job)=self.job.as_ref(){return if self.done{if semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(job){Ok(header::<Option<protocol::HistoryFoldJob<'static,Output>>>())}else{job.next_original_close_demand(body)}}else if job.original_output_ready(){Ok(protocol::HistoryFoldJob::<Output>::original_output_demand())}else if job.original_rejection_ready(){Ok(header::<TransitionFailure>())}else{job.original_step_demand(body)}}if self.input.is_some(){let input=&mut self.input;let runner=|control|original_future(input,control);return protocol::HistoryFoldJob::<Output>::original_birth_demand(&runner)}Ok(header::<Self>())}
 pub fn active(&self)->bool{!self.terminal_is_empty()}
 pub fn terminal_is_empty(&self)->bool{self.input.is_none()&&self.job.is_none()&&self.output.is_none()&&self.retirement.is_none()&&self.failure.is_none()&&self.binding.is_none()}
 pub fn advance(&mut self,source:Option<NativeSupersessionSource<'_>>,table:&mut crate::EffectiveSupersessions,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{
  self.advance_input(source,table,None,cx)
 }
 pub fn advance_at(&mut self,source:Option<NativeSupersessionSource<'_>>,table:&mut crate::EffectiveSupersessions,position:&mut usize,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{
  self.advance_input(source,table,Some(position),cx)
 }
 fn advance_input(&mut self,source:Option<NativeSupersessionSource<'_>>,table:&mut crate::EffectiveSupersessions,position:Option<&mut usize>,cx:&mut StepContext<'_>)->Result<Option<bool>,OriginalTurnFailure>{
  if self.closing{return Err(invalid("closing original supersession fold cannot resume").into())}let Some(source)=source else{return Ok(Some(false))};let event=source.event;if let Some(previous)=source.previous{if(previous.timestamp.cmp_key(),previous.mutation_id.0.as_str())>=(event.timestamp.cmp_key(),event.mutation_id.0.as_str()){return Err(invalid("original history transitions are not ordered by timestamp and identity").into())}}
  if self.binding.is_some_and(|(original,address)|!original.matches(cx)||address!=event as*const _ as usize){return Err(invalid("original supersession fold changed its source or caller").into())}
  if self.failure.is_some(){
   if self.failure.as_ref().unwrap().text.is_none(){use std::fmt::Write;let mut count=Count(0);write!(&mut count,"{}",self.failure.as_ref().unwrap().source).map_err(|_|invalid("original transition diagnostic extent overflow"))?;let d=RetirementDemand{copy_bytes:count.0+size_of::<String>(),capacity_bytes:count.0,depth:1,release_bytes:0};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{let mut text=String::with_capacity(count.0);write!(&mut text,"{}",self.failure.as_ref().unwrap().source).unwrap();self.failure.as_mut().unwrap().text=Some(text);Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;return Ok(None)}
   if let Some(failure)=semio_framework_job::admit_original_domain_failure(&mut self.failure,cx)?{return Err(failure)}return Ok(None)
  }
  if self.retirement.is_some(){self.close_residue(cx)?;return Ok(None)}let grant=cx.retained_grant();
  if self.done{if self.close_job(cx)?{let d=RetirementDemand{copy_bytes:size_of::<Self>()+usize::from(position.is_some())*size_of::<usize>(),depth:1,..Default::default()};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{self.binding=None;self.done=false;self.offset=0;if let Some(position)=position{*position+=1;}Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(output.map(|()|true))}return Ok(None)}
  if !protocol::is_history_transition(event){let d=header::<usize>();let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{if let Some(position)=position{*position+=1;}Ok((true,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(output)}
  if self.input.is_none()&&self.job.is_none()&&self.output.is_none(){let text=source.document.len();let d=RetirementDemand{copy_bytes:size_of::<Self>()+text,capacity_bytes:text,depth:1,release_bytes:0};let original=OriginalSourceBinding::borrow(cx);let address=event as*const _ as usize;admit_original_construction(cx,&mut self.input,physical(d),|_|{let input=(protocol::CausalPayload::default(),protocol::ArtifactId(source.document.to_owned()));self.binding=Some((original,address));Ok((input,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;return Ok(None)}
  if let Some(input)=self.input.as_mut(){if self.offset<event.diff.payload.len(){let backing=input.0.byte_backing_demand()?;if backing.capacity_bytes!=0{let d=RetirementDemand{copy_bytes:backing.copy_bytes+size_of::<usize>(),..backing};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{let mut p=input.0.reserve_byte_backing(grant)?;p.copied_bytes+=size_of::<usize>();Ok(((),p))})?;return Ok(None)}let bytes=(event.diff.payload.len()-self.offset).min(input.0.retained_bytes().capacity()-input.0.len()).min(4096-size_of::<usize>()).min(grant.maximum_copy_bytes.saturating_sub(size_of::<usize>()));if bytes==0{return Ok(None)}let d=RetirementDemand{copy_bytes:bytes+size_of::<usize>(),depth:input.0.retained_bytes().next_push_depth_demand().map_err(ValueError::from)?,..Default::default()};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{let mut fragment=[0;4096];let count=semio_framework_value::ByteReadSource::read_bytes(&event.diff.payload,self.offset,&mut fragment[..bytes]);if count!=bytes{return Err(invalid("original transition payload source changed while receiving"))}for byte in &fragment[..count]{input.0.push_reserved_byte(*byte)?;}self.offset+=count;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(None)}}

  if self.job.is_none()&&self.output.is_none(){let input=&mut self.input;let job=&mut self.job;let mut runner=Some(|control:protocol::HistoryFoldControl|original_future(input,control));let d=protocol::HistoryFoldJob::original_birth_demand(runner.as_ref().unwrap())?;if !permits(grant,d){return Ok(None)}receive(cx,|control|protocol::HistoryFoldJob::admit_original(&mut runner,job,control))?;return Ok(None)}
  if self.output.is_none(){let job=self.job.as_mut().unwrap();if job.original_rejection_ready(){let d=header::<TransitionFailure>();admit_original_construction(cx,&mut self.failure,physical(d),|_|Ok((TransitionFailure{source:job.take_rejection().unwrap(),text:None},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))?;return Ok(None)}if job.original_output_ready(){if !permits(grant,protocol::HistoryFoldJob::<Output>::original_output_demand()){return Ok(None)}receive(cx,|control|job.take_original_output(&mut self.output,control))?;}else{let body=grant.maximum_copy_bytes.min(4096);let d=job.original_step_demand(body)?;if !permits(grant,d){return Ok(None)}receive(cx,|control|job.step_original(control,body))?;}return Ok(None)}
  let output=self.output.as_mut().unwrap();let line=source.line.filter(|line|*line!=output.1).unwrap_or(output.1.as_str());
  if let protocol::HistoryTransition::Supersede(supersede)=&mut output.0{if !supersede.scope.as_deref().is_some_and(|scope|scope!=line){if let Some(input)=supersede.inputs.last(){let capacity=table.next_insert_capacity_byte_demand(&input.target,grant.maximum_copy_bytes)?;let depth=table.next_insert_depth_demand(&input.target)?;if capacity!=0{let d=RetirementDemand{capacity_bytes:capacity,depth,..Default::default()};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|table.reserve_insert_step(&input.target,grant).map(|p|((),p)).map_err(|(error,p)|error.with_retained_progress(p)))?;return Ok(None)}let texts=event.mutation_id.0.len()+supersede.scope.as_ref().map_or(0,String::len);let d=RetirementDemand{copy_bytes:size_of::<(protocol::MutationId,protocol::EffectiveSupersession)>()+texts,capacity_bytes:texts,depth,release_bytes:0};let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{let input=supersede.inputs.pop().unwrap();let value=protocol::EffectiveSupersession{transition_id:event.mutation_id.0.clone(),actor:event.actor.0.clone(),timestamp:event.timestamp,scope:supersede.scope.clone(),replacement:input.replacement};let(previous,_)=table.insert_reserved(input.target,value,grant).unwrap_or_else(|_|unreachable!("original supersession index was reserved"));if let Some(previous)=previous{self.retirement=Some(ControlledRetirement::retain(Residue::Supersession(previous)));}Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))})?;return Ok(None)}}}
  let d=header::<Output>();let mut output=None;admit_original_construction(cx,&mut output,physical(d),|_|{self.retirement=Some(ControlledRetirement::retain(Residue::Output(self.output.take().unwrap())));self.done=true;Ok(((),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(None)
 }
 fn close_residue(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let owner=self.retirement.as_ref().unwrap();if owner.terminal_is_empty(){let d=header::<Option<ControlledRetirement<Residue>>>();close_original_retained_step(cx,d,|_|{self.retirement=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|self.retirement.as_mut().unwrap().step(grant))?;}Ok(())}
 fn close_job(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{let Some(job)=self.job.as_ref()else{return Ok(true)};if semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(job){let d=header::<Option<protocol::HistoryFoldJob<'static,Output>>>();close_original_retained_step(cx,d,|_|{self.job=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;}else{let d=job.next_original_close_demand(cx.retained_grant().maximum_copy_bytes)?;let grant=cx.retained_grant();if !permits(grant,d){return Ok(false)}let result=cx.with_native_retirement(|native|self.job.as_mut().unwrap().close_original(native,grant));let p=result.as_ref().map(|step|step.progress()).unwrap_or_else(|error|error.retained_progress());cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);result?;}Ok(self.job.is_none())}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(owner)=self.retirement.as_ref(){return if owner.terminal_is_empty(){Ok(header::<Option<ControlledRetirement<Residue>>>())}else{owner.next_demand(body)}}if let Some(job)=self.job.as_ref(){return if semio_framework_value::ErasedSnapshotRetirement::terminal_is_empty(job){Ok(header::<Option<protocol::HistoryFoldJob<'static,Output>>>())}else{job.next_original_close_demand(body)}}Ok(header::<Self>())}
 pub fn close(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.terminal_is_empty(){return Ok(true)}self.begin_close();if self.retirement.is_some(){self.close_residue(cx)?;return Ok(false)}if !self.close_job(cx)?{return Ok(false)}if self.input.is_some()||self.output.is_some()||self.failure.is_some(){let d=header::<Self>();close_original_retained_step(cx,d,|_|{self.retirement=Some(ControlledRetirement::retain(if let Some(failure)=self.failure.take(){Residue::Failure(failure)}else if let Some(input)=self.input.take(){Residue::Input(input)}else{Residue::Output(self.output.take().unwrap())}));Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;return Ok(false)}let d=header::<Self>();close_original_retained_step(cx,d,|_|{self.binding=None;self.done=false;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(self.terminal_is_empty())}
}
impl Drop for NativeSupersessionFold{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original supersession fold must finish its native output and source closure")}}

fn permits(grant:RetainedCloneGrant,d:RetirementDemand)->bool{semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d)}

fn original_future(input:&mut Option<Input>,control:protocol::HistoryFoldControl)->impl std::future::Future<Output=Result<Output,protocol::ProtocolError>>+Send+'static{let source=control.track(input.take().unwrap()).unwrap_or_else(|_|unreachable!("original transition input declares typed retirement"));async move{let source=source.await;let transition=protocol::decode_history_transition_controlled(&source.0,&control).await?;let trunk=protocol::copy_history_trunk(&source.1,&control).await?;Ok((transition,trunk))}}
